    New-Item -ItemType Directory -Force -Path "$($PathDrive)PipTheMochi$($PathIdNumberPip)" -ErrorAction Stop
} catch {    
    $Decision = [System.Windows.MessageBox]::Show("Folder PipTheMochi1 could not be created, Pip The Mochi failed!", "System Error", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Error)
    pause ; start powershell "-NoExit Write-Host Do not want this window to type commands? Try typing exit instead! You have gotten this window from errors. ; Write-host Seems like the folder could not be created, if you are running with the right permissions, try closing all the windows that have ran Pip before, and try running Pip again! ; cd $($PathDrive)PipTheMochi$($PathIdNumberPip)" ; exit
}

#region unpack base 64 (non-images)

$Base64StringSettings = ""

$OutputPathSettings = "$($PathDrive)PipTheMochi$($PathIdNumberPip)\Settings.ps1"

$ImageBytesSettings = [System.Convert]::FromBase64String($Base64StringSettings)
[System.IO.File]::WriteAllBytes($OutputPathSettings, $ImageBytesSettings)

# Game

$Base64StringGame = ""

$OutputPathGame = "$($PathDrive)PipTheMochi$($PathIdNumberPip)\Game.zip"
$OutputPathGameOutside = "$($PathDrive)PipTheMochi$($PathIdNumberPip)"

$ImageBytesGame = [System.Convert]::FromBase64String($Base64StringGame)
[System.IO.File]::WriteAllBytes($OutputPathGame, $ImageBytesGame)

Start-Sleep -Milliseconds 200

Expand-Archive -LiteralPath "$OutputPathGame" -DestinationPath "$OutputPathGameOutside" -Force

Start-Sleep -Milliseconds 200

#endregion

# 1. Define where you want the 600-byte image saved
$OutputPath1 = "$($PathDrive)PipTheMochi$($PathIdNumberPip)\PipIdle.png"
$OutputPath2 = "$($PathDrive)PipTheMochi$($PathIdNumberPip)\PipOver.png"
$OutputPath3 = "$($PathDrive)PipTheMochi$($PathIdNumberPip)\PipDrag.png"
$OutputPath4 = "$($PathDrive)PipTheMochi$($PathIdNumberPip)\PipFast.png"
$OutputPath5 = "$($PathDrive)PipTheMochi$($PathIdNumberPip)\PipDrop.png"

if ($CreateOrOverwriteFilesOrImages -eq "1") {

    # 2. Your actual 800-character Base64 string goes here
    $Base64String1 = ""

    $Base64String2 = ""

    $Base64String3 = ""

    $Base64String4 = ""

    $Base64String5 = ""

    try {
        # 3. Decode and compile the file
        $ImageBytes = [System.Convert]::FromBase64String($Base64String1)
        [System.IO.File]::WriteAllBytes($OutputPath1, $ImageBytes)
        $ImageBytes = [System.Convert]::FromBase64String($Base64String2)
        [System.IO.File]::WriteAllBytes($OutputPath2, $ImageBytes)
        $ImageBytes = [System.Convert]::FromBase64String($Base64String3)
        [System.IO.File]::WriteAllBytes($OutputPath3, $ImageBytes)
        $ImageBytes = [System.Convert]::FromBase64String($Base64String4)
        [System.IO.File]::WriteAllBytes($OutputPath4, $ImageBytes)
        $ImageBytes = [System.Convert]::FromBase64String($Base64String5)
        [System.IO.File]::WriteAllBytes($OutputPath5, $ImageBytes)
    } catch {
