$Padding = ($BorderSize * 2) + 32
$ImgWidth = ($ImgPip1.PixelWidth * $Scale)
$ImgHeight = ($ImgPip1.PixelHeight * $Scale)
# $ImgWidth + $Padding
$WinWidth = 850
$WinHeight = $ImgHeight + $Padding + 140 # <── Changed from 60 to 140 to stop the clipping!

# 5. CONSTRUCT THE IMAGE CONTROL COMPONENT
$ImageControl = New-Object System.Windows.Controls.Image
$ImageControl.Source = $ImgPip1
$ImageControl.Width = $ImgWidth
$ImageControl.Height = $ImgHeight
$ImageControl.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Center
$ImageControl.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
[System.Windows.Media.RenderOptions]::SetBitmapScalingMode($ImageControl, [System.Windows.Media.BitmapScalingMode]::NearestNeighbor)

# 6. SOLID BORDER EFFECTS
$GroupEffect = New-Object System.Windows.Media.Effects.DropShadowEffect
$GroupEffect.Color = [System.Windows.Media.Color]::FromRgb(0, 0, 0); $GroupEffect.BlurRadius = 0; $GroupEffect.ShadowDepth = $BorderSize; $GroupEffect.Direction = 0; $GroupEffect.Opacity = 1.0

$EffectL = New-Object System.Windows.Media.Effects.DropShadowEffect
$EffectL.Color = [System.Windows.Media.Color]::FromRgb(0, 0, 0); $EffectL.BlurRadius = 0; $EffectL.ShadowDepth = $BorderSize; $EffectL.Direction = 180; $EffectL.Opacity = 1.0

$EffectT = New-Object System.Windows.Media.Effects.DropShadowEffect
$EffectT.Color = [System.Windows.Media.Color]::FromRgb(0, 0, 0); $EffectT.BlurRadius = 0; $EffectT.ShadowDepth = $BorderSize; $EffectT.Direction = 90; $EffectT.Opacity = 1.0

$EffectB = New-Object System.Windows.Media.Effects.DropShadowEffect
$EffectB.Color = [System.Windows.Media.Color]::FromRgb(0, 0, 0); $EffectB.BlurRadius = 0; $EffectB.ShadowDepth = $BorderSize; $EffectB.Direction = 270; $EffectB.Opacity = 1.0

#  CHOOSE THIS CORRECT REPLACEMENT:
$Panel1 = New-Object System.Windows.Controls.Decorator; $Panel1.Effect = $EffectL
$Panel2 = New-Object System.Windows.Controls.Decorator; $Panel2.Effect = $EffectT
$Panel3 = New-Object System.Windows.Controls.Decorator; $Panel3.Effect = $EffectB

# Stack both layout elements together smoothly inside a vertical Grid
$Grid = New-Object System.Windows.Controls.Grid

# FIX 1: Lock the layout sizes permanently so Pip cannot bounce!
$Row0 = New-Object System.Windows.Controls.RowDefinition
$Row0.Height = New-Object System.Windows.GridLength(110, [System.Windows.GridUnitType]::Pixel) # <── Fixed overhead text room

$Row1 = New-Object System.Windows.Controls.RowDefinition
$Row1.Height = [System.Windows.GridLength]::Auto # <── Pip's native image room
$Grid.RowDefinitions.Add($Row0)
$Grid.RowDefinitions.Add($Row1)

[System.Windows.Controls.Grid]::SetRow($textControl, 0)
[System.Windows.Controls.Grid]::SetRow($ImageControl, 1)

$Grid.Children.Add($textControl) | Out-Null
$Grid.Children.Add($ImageControl) | Out-Null


$Panel1.Child = $Grid; $Panel2.Child = $Panel1; $Panel3.Child = $Panel2
$ImageControl.Effect = $GroupEffect

# 7. WINDOW ASSEMBLY
$Window = New-Object System.Windows.Window
$Window.Title = "PipTheMochi"
$Window.Width = $WinWidth
$Window.Height = $WinHeight
$Window.WindowStyle = [System.Windows.WindowStyle]::None
$Window.ResizeMode = [System.Windows.ResizeMode]::NoResize
$Window.ShowInTaskbar = $false
$Window.Topmost = $true
$Window.WindowStartupLocation = [System.Windows.WindowStartupLocation]::CenterScreen
$Window.AllowsTransparency = $true
$Window.Background = [System.Windows.Media.Brushes]::Transparent
$Window.Content = $Panel3

# Share instance reference with global scope for engine synchronization hooks
$Script:textControl = $textControl

$Script:CurrentVoiceState = "Hello"
Say-Text (Get-RandomLine "Hello")   

# ─── DRAG & DROP ENTITLEMENTS ───
$Window.AllowDrop = $true

# STAGE SWAPPER
function Switch-Stage ($WpfImage) {
    if ($null -ne $WpfImage -and $ImageControl.Source -ne $WpfImage) {
        $ImageControl.Source = $WpfImage
        
        if ($WpfImage -eq $ImgPip4 -and $Script:CurrentVoiceState -ne "Shake") {
            $Script:CurrentVoiceState = "Shake"
            Say-Text (Get-RandomLine "Shake")
        }
    }
}

# 8. DRAG-PROOF INTERACTIVE RENDERING STATE ENGINE
$Script:IsDragging = $false
$Script:LastWindowPos = New-Object System.Windows.Point($Window.Left, $Window.Top)
$Script:ShakeIntensity = 0
$ShakeDecay = 0.82

$RenderLoopHandler = {
    if ($Script:IsDragging) {
        $CurrentWindowPos = New-Object System.Windows.Point($Window.Left, $Window.Top)
        
        $DistX = $CurrentWindowPos.X - $Script:LastWindowPos.X
        $DistY = $CurrentWindowPos.Y - $Script:LastWindowPos.Y
        $DistanceMoved = [Math]::Sqrt(($DistX * $DistX) + ($DistY * $DistY))
        
        $Script:ShakeIntensity = ($Script:ShakeIntensity * $ShakeDecay) + $DistanceMoved
        
        if ($Script:ShakeIntensity -gt $ShakeSensitivity -and $ImgPip4) {
            Switch-Stage $ImgPip4
        } elseif ($ImgPip3) {
            if ($Script:CurrentVoiceState -ne "Drag" -and $Script:CurrentVoiceState -ne "Shake") {
                $Script:CurrentVoiceState = "Drag"
                Say-Text (Get-RandomLine "Drag")
            }
            Switch-Stage $ImgPip3
        }
        
        $Script:LastWindowPos = $CurrentWindowPos
    } else {  # <─── Added the missing closing bracket right here!
        # ─── STANDBY RANDOM TALK ENGINE ───
        $Script:CountTalkTimer += 16
        if ($Script:CountTalkTimer -ge $TalkTimer) {
            $Script:CountTalkTimer = 0
            # Set the next random chat interval (e.g., between 25.5 and 45.5 seconds)
            <#$Window.Left += 100#>
            $TalkTimer = (Get-Random -Minimum $TalkMin -Maximum $TalkMax)
                
            if (-not $Script:IsDragging -and ($Script:CurrentVoiceState -eq "Idle" -or $Script:CurrentVoiceState -eq "")) {
                $Script:CurrentVoiceState = "Talk"
                Say-Text (Get-RandomLine "Talk")
                $Script:CurrentVoiceState = "Idle"
                # Start a countdown to hide the text window
                $Script:TextHideCountdown = 4000 
            }
        }

        # Automatically clear text bubble when Pip finishes speaking
        if ($null -ne $Script:TextHideCountdown) {
            $Script:TextHideCountdown -= 16
            if ($Script:TextHideCountdown -le 0) {
                $Script:TextHideCountdown = $null
                if ($Script:CurrentVoiceState -eq "Idle") {
                    $textControl.Visibility = [System.Windows.Visibility]::Collapsed
                }
            }
        }
    }
}

[System.Windows.Media.CompositionTarget]::add_Rendering($RenderLoopHandler)

# 9. MOUSE HOVER ROUTINES
$Grid.Add_MouseEnter({ 
    if (-not $Script:IsDragging -and $ImgPip2 -and $Script:CurrentVoiceState -ne "FileDropProcessing") { 
        if ($Script:CurrentVoiceState -ne "Hover") {
            $Script:CurrentVoiceState = "Hover"
            Say-Text (Get-RandomLine "Hover")   
        }
        Switch-Stage $ImgPip2 
    } 
})

$Grid.Add_MouseLeave({ 
    if (-not $Script:IsDragging -and $Script:CurrentVoiceState -ne "FileDropProcessing") { 
        $Script:CurrentVoiceState = "Idle"
        $textControl.Visibility = [System.Windows.Visibility]::Collapsed
        Switch-Stage $ImgPip1 
    } 
})

# 10. FILE DRAG & DROP ENGINE HANDLERS
$Window.Add_DragEnter({
    if ($_.Data.GetDataPresent([System.Windows.DataFormats]::FileDrop)) {
        $_.Effects = [System.Windows.DragDropEffects]::Copy
    }
})

$Window.Add_Drop({ 
    if ($_.Data.GetDataPresent([System.Windows.DataFormats]::FileDrop)) { 
        if ($AllowEatting -eq "1") { 
            $Files = $_.Data.GetData([System.Windows.DataFormats]::FileDrop) 
            if ($Files.Count -gt 0) { 
                $TargetFile = $Files[0] 
                $Script:CurrentVoiceState = "FileDropProcessing" 
                if ($ImgPip5) { Switch-Stage $ImgPip5 } 
                Say-Text (Get-RandomLine "Drop") 
                $FileName = [System.IO.Path]::GetFileName($TargetFile) 
                $Decision = [System.Windows.MessageBox]::Show("Should I eat '$FileName'?", "Accept Deletion of File", [System.Windows.MessageBoxButton]::YesNo, [System.Windows.MessageBoxImage]::Warning) 
                if ($Decision -eq [System.Windows.MessageBoxResult]::Yes) { 
                    try { 
                        Remove-Item -Path $TargetFile -Force -ErrorAction Stop -recurse 
                    } catch { 
                        [System.Windows.MessageBox]::Show("Could not delete file: $_", "Error", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Error) 
                    } 
                } 
                $Script:CurrentVoiceState = "Idle" 
                $textControl.Visibility = [System.Windows.Visibility]::Collapsed 
                Switch-Stage $ImgPip1 
            } 
        } else { 
            Write-Host "I'm not allowed to eat!"
        } 
    } 
})

# 11. INTEGRATED WINDOWS DRAG ROUTINES
$Grid.Add_MouseDown({
    if ($Script:CurrentVoiceState -eq "FileDropProcessing") { return }
    
    if ($_.ChangedButton -eq [System.Windows.Input.MouseButton]::Left) {
        $Script:IsDragging = $true
        $Script:ShakeIntensity = 0
        $Script:LastWindowPos = New-Object System.Windows.Point($Window.Left, $Window.Top)
        
        if ($ImgPip3) { 
            $Script:CurrentVoiceState = "Drag"
            Say-Text (Get-RandomLine "Drag") 
            Switch-Stage $ImgPip3 
        }
        
        $Window.DragMove()
        
        $Script:IsDragging = $false
        
        $MouseOverPos = [System.Windows.Input.Mouse]::GetPosition($Window)
        if ($MouseOverPos.X -ge 0 -and $MouseOverPos.X -le $Window.Width -and $MouseOverPos.Y -ge 0 -and $MouseOverPos.Y -le $Window.Height) {
            if ($ImgPip2) { $Script:CurrentVoiceState = "Hover"; Switch-Stage $ImgPip2 } else { $Script:CurrentVoiceState = "Idle"; Switch-Stage $ImgPip1 }
        } else {
            $Script:CurrentVoiceState = "Idle"
            $textControl.Visibility = [System.Windows.Visibility]::Collapsed
            Switch-Stage $ImgPip1
        }
    }
})

<#
$TalkMin = $TalkMinOrg
$TalkMax = $TalkMaxOrg

$TalkMin = $MaxNumber - 1
$TalkMax = $MaxNumber
#>

$Window.Add_KeyDown({ 
    if ($_.Key -eq [System.Windows.Input.Key]::Escape) { 
        <#
        $Script:CurrentVoiceState = "Bye"
        Say-Text (Get-RandomLine "Bye")   
        $Decision = [System.Windows.MessageBox]::Show("Should I, Pip the Mochi, leave?", "Accept Closing of Pip the Mochi", [System.Windows.MessageBoxButton]::YesNo, [System.Windows.MessageBoxImage]::Question)
            
        if ($Decision -eq [System.Windows.MessageBoxResult]::Yes) {
            write-host "Quiting Pip!..."
            [System.Windows.Media.CompositionTarget]::remove_Rendering($RenderLoopHandler)
            $Script:SpeechRunspace.Stop()
            $Window.Close() 
        } else {
            write-host "Stopping Pip from quiting!..."
            $Script:CurrentVoiceState = "Idle"
            $textControl.Visibility = [System.Windows.Visibility]::Collapsed
        }
        #>
        # 1. Create the right-click menu container
        $PipContextMenu = New-Object System.Windows.Controls.ContextMenu


        # 3. Design the second menu item (The Shutup button)
        $MenuItemMute = New-Object System.Windows.Controls.MenuItem
        $MenuItemMute.Header = "Mute or unmute Pip from talking"
        $MenuItemMute.Add_Click({
            $Decision = [System.Windows.MessageBox]::Show("Should I, Pip the Mochi, stop talking?", "Accept the discontinuing of Pip the Mochi talking", [System.Windows.MessageBoxButton]::YesNo, [System.Windows.MessageBoxImage]::Question)
    
            if ($Decision -eq [System.Windows.MessageBoxResult]::Yes) {
                write-host "Muting Pip!..."
                # FIX: Activate the absolute mute flag logic block
                $Script:IsMuted = $true
        
                # Collapse any existing visible overlay bubble instantly
                $textControl.Visibility = [System.Windows.Visibility]::Collapsed
        
                $TalkMin = $MaxNumber - 1
                $TalkMax = $MaxNumber
                $TalkTimer = $MaxNumber 
                $CountTalkTimer = 0
                Write-Host "Pip has been muted."
            } else {
                write-host "Unmuting Pip!..."
                # FIX: Restore natural behaviors cleanly
                $Script:IsMuted = $false
        
                $TalkMin = $TalkMinOrg
                $TalkMax = $TalkMaxOrg
                $TalkTimer = (Get-Random -Minimum $TalkMin -Maximum $TalkMax)
                $CountTalkTimer = 0
                Write-Host "Pip has been unmuted."
            }
        })

        # 2. Design the first menu item (The Game Launcher!)
        $MenuItemQuit = New-Object System.Windows.Controls.MenuItem
        $MenuItemQuit.Header = "Make Pip go away"
        $MenuItemQuit.Add_Click({
            $Script:CurrentVoiceState = "Bye"
            Say-Text (Get-RandomLine "Bye")   
            $Decision = [System.Windows.MessageBox]::Show("Should I, Pip the Mochi, leave?", "Accept Closing of Pip the Mochi", [System.Windows.MessageBoxButton]::YesNo, [System.Windows.MessageBoxImage]::Question)
            
            if ($Decision -eq [System.Windows.MessageBoxResult]::Yes) {
                write-host "Quiting Pip!..."
                [System.Windows.Media.CompositionTarget]::remove_Rendering($RenderLoopHandler)
                $Script:SpeechRunspace.Stop()
                $Window.Close() 
            } else {
                write-host "Stopping Pip from quiting!..."
                $Script:CurrentVoiceState = "Idle"
                $textControl.Visibility = [System.Windows.Visibility]::Collapsed
            }
        })

        # 2. Design the first menu item (The Game Launcher!)
        $MenuItemGame = New-Object System.Windows.Controls.MenuItem
        $MenuItemGame.Header = "Launch a TurboWarp game"
        $MenuItemGame.Add_Click({
            $Decision = [System.Windows.MessageBox]::Show("Should I, Pip the Mochi, spawn a game?", "Accept the action of Pip the Mochi summoning a game", [System.Windows.MessageBoxButton]::YesNo, [System.Windows.MessageBoxImage]::Question)
                
            if ($Decision -eq [System.Windows.MessageBoxResult]::Yes) {
                write-host "Spawning game!..."
                # Define the path to your HTML file
                $htmlPath = "$($PathDrive)PipTheMochi$($PathIdNumberPip)\Test Project.html"

                # Format the local path into a file:// URI
                $fileUri = [System.Uri]$htmlPath

                # We create a tiny temp folder in your system cache to bypass Chrome's memory
                $tempProfile = "$env:TEMP\chrome_app_360x480"

                # Launch Chrome completely isolated so it forces the size
                Start-Process -FilePath "C:\Program Files\Google\Chrome\Application\chrome.exe" -ArgumentList `
                    "--app=`"$fileUri`"", 
                    "--window-size=960,752", 
                    "--user-data-dir=`"$tempProfile`""
            }
        })

        # 4. Attach the items to the menu, and attach the menu to Pip
        $PipContextMenu.Items.Add($MenuItemMute) | Out-Null
        $PipContextMenu.Items.Add($MenuItemQuit) | Out-Null
        $PipContextMenu.Items.Add($MenuItemGame) | Out-Null
        $ImageControl.ContextMenu = $PipContextMenu

        # 🚀 ADD This line to force it to open immediately!
        $PipContextMenu.IsOpen = $true
    } <# else {
        if ($_.Key -eq [System.Windows.Input.Key]::S) { 
            $Decision = [System.Windows.MessageBox]::Show("Should I, Pip the Mochi, stop talking?", "Accept the discontinuing of Pip the Mochi talking", [System.Windows.MessageBoxButton]::YesNo, [System.Windows.MessageBoxImage]::Question)
    
            if ($Decision -eq [System.Windows.MessageBoxResult]::Yes) {
                write-host "Muting Pip!..."
                # FIX: Activate the absolute mute flag logic block
                $Script:IsMuted = $true
        
                # Collapse any existing visible overlay bubble instantly
                $textControl.Visibility = [System.Windows.Visibility]::Collapsed
        
                $TalkMin = $MaxNumber - 1
                $TalkMax = $MaxNumber
                $TalkTimer = $MaxNumber 
                $CountTalkTimer = 0
                Write-Host "Pip has been muted."
            } else {
                write-host "Unmuting Pip!..."
                # FIX: Restore natural behaviors cleanly
                $Script:IsMuted = $false
        
                $TalkMin = $TalkMinOrg
                $TalkMax = $TalkMaxOrg
                $TalkTimer = (Get-Random -Minimum $TalkMin -Maximum $TalkMax)
                $CountTalkTimer = 0
                Write-Host "Pip has been unmuted."
            }
        } else {
            if ($_.Key -eq [System.Windows.Input.Key]::G) { 
                $Decision = [System.Windows.MessageBox]::Show("Should I, Pip the Mochi, spawn a game?", "Accept the action of Pip the Mochi summoning a game", [System.Windows.MessageBoxButton]::YesNo, [System.Windows.MessageBoxImage]::Question)
                
                if ($Decision -eq [System.Windows.MessageBoxResult]::Yes) {
                    write-host "Spawning game!..."
                    # Define the path to your HTML file
                    $htmlPath = "$($PathDrive)PipTheMochi$($PathIdNumberPip)\Test Project.html"

                    # Format the local path into a file:// URI
                    $fileUri = [System.Uri]$htmlPath

                    # We create a tiny temp folder in your system cache to bypass Chrome's memory
                    $tempProfile = "$env:TEMP\chrome_app_360x480"

                    # Launch Chrome completely isolated so it forces the size
                    Start-Process -FilePath "C:\Program Files\Google\Chrome\Application\chrome.exe" -ArgumentList `
                        "--app=`"$fileUri`"", 
                        "--window-size=960,752", 
                        "--user-data-dir=`"$tempProfile`""
                }
            }
        }
    } #>
})

try {
    # 12. LAUNCH OVERLAY
    $Window.ShowDialog() | Out-Null
} catch {
    $Decision = [System.Windows.MessageBox]::Show("Overlay could not be launched, Pip The Mochi failed!", "System Error", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Error)
    pause ; start powershell "-NoExit Write-Host Do not want this window to type commands? Try typing exit instead! You have gotten this window from errors. ; Write-host Seems like the overlay could not be lauched, are you using Windows 10 or 11? Or is something blocking the overlay? ; cd $($PathDrive)PipTheMochi$($PathIdNumberPip)" ; exit
}
